class PrincipalComponentAnalysis(PCA):

    def __init__(self, stat_list, stat_params = None, n_components = 20, svd_solver = 'full', \
                 scale = 'max_variance', save_stat_list = False):

        # Writing the type of scaling as attributed
        self.scale = scale

        # Set n_components to min dimension of full statistics data matrix
        min_dim = np.min(np.hstack(stat_list).shape)
        if n_components > min_dim:
            n_components = min_dim

        # Inheritance of PCA class of sklearn package
        PCA.__init__(self, n_components = n_components, svd_solver = svd_solver)

        # Scaling the features based on user input
        if stat_list.__len__() > 1:
            stat_list, scaling_factors = feature_scaler(stat_list, scale)
            self.scaling_factors = scaling_factors

        # Converting the list of set of statistics to a single data matrix
        stat_list = np.hstack(stat_list)

        # Calculation of PC scores
        self.Scores = self.fit_transform(stat_list)

        # Writing the scaled stat_list as attribute
        if save_stat_list:
            self.scaled_stats = stat_list


    # Method for saving PC scores for later use in model builder
    def save_scores_model_builder(self, trunc_level, save_path, sample_id = None, mat_proc_prop = None, \
                                  averaging = False):

        # Setting the truncation level for PC basis
        if trunc_level > self.Scores.shape[1]:
            trunc_level = self.Scores.shape[1]

        # Preparing feature names of the dataframe
        feature_names = ['PC ' + str(i + 1) for i in range(trunc_level)]

        # Preparing the dataframe of PC scores
        df = pd.DataFrame(self.Scores[:, :trunc_level], columns = feature_names)

        # Writing process parameters/properties to dataframe
        if mat_proc_prop is not None:
            for key in mat_proc_prop.keys():
                if mat_proc_prop[key].shape[0] != self.Scores.shape[0]:
                    raise ValueError('The number of entries in material properties, process conditions '\
                                     'and sample_id must be equal to the number of entries in PC scores '\
                                     '(i.e. the number of microstructures or rows in tabular data)')
                else:
                    df[key] = mat_proc_prop[key]

        # Writing the sample key to dataframe
        if sample_id is not None:

            if sample_id.__len__() != self.Scores.shape[0]:
                raise ValueError('The number of entries in material properties, process conditions '\
                                 'and sample_id must be equal to the number of entries in PC scores '\
                                 '(i.e. the number of microstructures or rows in tabular data)')
            else:
                df['sample_id'] = sample_id
                # Taking the mean of the PC scores, process conditions and properties
                if averaging:
                    df = df.groupby('sample_id').mean()

        # Saving the dataframe to parquet file
        df.to_parquet(save_path) #to_csv(save_path, index = False)


    # Transformation (i.e. projecting new data to the existing PC space)
    def fit_pca(self, new_stat_list):

        # Scale the new_stat_list based on the scaling factors
        if new_stat_list.__len__() > 1:
            # The case with featurewise_variance
            if isinstance(self.scaling_factors, StandardScaler):
                new_stat_list = sc.transform(np.hstack(new_stat_list))
            else:
                for i in range(len(new_stat_list)):
                    new_stat_list[i] = new_stat_list[i] / self.scaling_factors[i]

        # Converting the list of set of statistics to a single data matrix
        new_stat_list = np.hstack(new_stat_list)

        return self.transform(new_stat_list)


    # Visualization of PC scores
    def visualize_scores(self, indices, feature = None, feature_name = None, feature_unit = None, \
                         fig = None, ax = None, return_fig = False):

        params = {'ax': ax, 'fig': fig, 'return_fig': return_fig, 'feature': feature, \
                  'feature_name': feature_name, 'feature_unit': feature_unit}

        # Calling TwoPoint visualization in FeatureEngineeringVisualization module as method
        fig_out = Visualize_PC_Scores(self.Scores, indices, **params)

        # Return figure (for platform purposes)
        if return_fig:
            return fig_out


